import{_ as t,c as r,o as a,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"测试与基准测试","description":"","frontmatter":{"title":"测试与基准测试","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#10","branch":"main","level":0,"order":10,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/10-testing-and-benchmarking/index.md","filePath":"posts/projects/zfeed/10-testing-and-benchmarking/index.md","lastUpdated":1779632679000}'),o={name:"posts/projects/zfeed/10-testing-and-benchmarking/index.md"};function n(c,e,l,s,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="测试与基准测试" tabindex="-1">测试与基准测试 <a class="header-anchor" href="#测试与基准测试" aria-label="Permalink to &quot;测试与基准测试&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/README.md?plain=1" target="_blank" rel="noreferrer">bench/ghz/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js" target="_blank" rel="noreferrer">bench/k6/config.js</a></li></ul></details><p>本节概述 <code>zfeed</code> 代码库采用的多层测试与基准测试策略。系统的测试层级从隔离的单元逻辑，到全栈端到端（E2E）验证，再到高并发性能测试套件。</p><h2 id="测试层级总览" tabindex="-1">测试层级总览 <a class="header-anchor" href="#测试层级总览" aria-label="Permalink to &quot;测试层级总览&quot;">​</a></h2><p>测试策略旨在保证分布式边界上的正确性，尤其关注数据一致性（幂等性）、Cache-Aside 可靠性，以及系统在负载下的性能表现。</p><h3 id="_1-单元测试与集成测试" tabindex="-1">1. 单元测试与集成测试 <a class="header-anchor" href="#_1-单元测试与集成测试" aria-label="Permalink to &quot;1. 单元测试与集成测试&quot;">​</a></h3><p>代码库使用专用工具模拟基础设施组件，而无需启动完整 Docker 栈。这使业务逻辑和仓储层可以被快速、隔离地验证。</p><ul><li>数据库模拟：仓储层集成测试，例如 <code>LikeRepository</code>，使用本地 MySQL 实例或 SQLite，并由 <code>mysqltest</code> 工具管理 schema 约束和行清理 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L29-L53" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#29-53</a></li><li>缓存模拟：使用 <code>miniredis</code> 在隔离环境中验证 Redis Lua 脚本和 TTL 逻辑。</li><li>Consumer 验证：<code>LikeConsumer</code> 等消息逻辑通过在测试数据库上模拟 Kafka payload，验证幂等性与事件合并行为 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L29-L62" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#29-62</a></li></ul><p>实现细节和模式请参见 <a href="./01-unit-and-integration-testing.html">单元测试与集成测试</a>。</p><h3 id="_2-端到端-e2e-测试" tabindex="-1">2. 端到端（E2E）测试 <a class="header-anchor" href="#_2-端到端-e2e-测试" aria-label="Permalink to &quot;2. 端到端（E2E）测试&quot;">​</a></h3><p>E2E 测试运行在真实 Docker Compose 栈上。这类测试验证跨多个微服务和基础设施组件（Canal、Kafka、Redis、MySQL）的“happy path”。</p><ul><li>链路验证：<code>TestCountChainE2E</code> 等测试验证一次互动，例如点赞，是否能正确穿过 <code>interaction-rpc</code> outbox、进入 Kafka、经由 <code>count-rpc</code> dispatcher，最终更新 <code>zfeed_count_value</code> 表。</li><li>系统状态：验证热门内容快照和可观测性流水线（Prometheus/Jaeger），确保线上操作期间 trace 和 metrics 能正确发出。</li></ul><h3 id="_3-性能基准测试" tabindex="-1">3. 性能基准测试 <a class="header-anchor" href="#_3-性能基准测试" aria-label="Permalink to &quot;3. 性能基准测试&quot;">​</a></h3><p><code>zfeed</code> 包含一套完整基准测试，用于度量系统上限并定位瓶颈。</p><ul><li>gRPC 基准测试：使用 <code>ghz</code> 直接压测 RPC 服务，例如在 <code>127.0.0.1:5001</code> 上针对 <code>feed-*</code> 使用合成数据集 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/README.md?plain=1#L1-L25" target="_blank" rel="noreferrer">bench/ghz/README.md#1-25</a></li><li>HTTP 负载测试：使用 <code>k6</code> 针对 <code>front-api</code> 网关模拟不同流量模式，包括 smoke、spike 和 soak 测试 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js#L57-L70" target="_blank" rel="noreferrer">bench/k6/config.js#57-70</a></li><li>场景覆盖：覆盖读密集（Feed 推荐）、写密集（社交互动）和搜索密集工作负载，并定义 SLO 阈值 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js#L7-L18" target="_blank" rel="noreferrer">bench/k6/config.js#7-18</a></li></ul><p>运行基准测试和 E2E 套件的详情请参见 <a href="./02-end-to-end-and-performance-testing.html">端到端与性能测试</a>。</p><h2 id="代码实体映射" tabindex="-1">代码实体映射 <a class="header-anchor" href="#代码实体映射" aria-label="Permalink to &quot;代码实体映射&quot;">​</a></h2><p>下图展示测试工具如何连接抽象测试概念与具体实现实体。</p><h3 id="测试基础设施关联" tabindex="-1">测试基础设施关联 <a class="header-anchor" href="#测试基础设施关联" aria-label="Permalink to &quot;测试基础设施关联&quot;">​</a></h3><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L29-L174" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#29-174</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L46-L79" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#46-79</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L198-L216" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#198-216</a></p><h3 id="基准测试套件结构" tabindex="-1">基准测试套件结构 <a class="header-anchor" href="#基准测试套件结构" aria-label="Permalink to &quot;基准测试套件结构&quot;">​</a></h3><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js#L1-L39" target="_blank" rel="noreferrer">bench/k6/config.js#1-39</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/README.md?plain=1#L9-L13" target="_blank" rel="noreferrer">bench/ghz/README.md#9-13</a></p><h2 id="关键测试工具" tabindex="-1">关键测试工具 <a class="header-anchor" href="#关键测试工具" aria-label="Permalink to &quot;关键测试工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>目标实体</th></tr></thead><tbody><tr><td><code>go test</code></td><td>单元/集成测试</td><td>服务逻辑、仓储层、MQ Consumer</td></tr><tr><td><code>miniredis</code></td><td>Redis 模拟</td><td>缓存逻辑、Lua 脚本、TTL 管理</td></tr><tr><td><code>mysqltest</code></td><td>MySQL schema 工具</td><td>GORM 仓储层、事务逻辑</td></tr><tr><td><code>k6</code></td><td>HTTP 负载测试</td><td><code>front-api</code> 网关、端到端用户流程</td></tr><tr><td><code>ghz</code></td><td>gRPC 基准测试</td><td>内部 RPC 服务方法</td></tr><tr><td><code>k3s/Docker</code></td><td>E2E 环境</td><td>完整服务栈（Kafka、Canal、Etcd）</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L1-L25" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#1-25</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/k6/config.js#L1-L5" target="_blank" rel="noreferrer">bench/k6/config.js#1-5</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/ghz/README.md?plain=1#L1-L7" target="_blank" rel="noreferrer">bench/ghz/README.md#1-7</a></p>',25)])])}const m=t(o,[["render",n]]);export{b as __pageData,m as default};
